KG_CODE("f:src/autoskill/browser/page.py","\"\"\"One controlled browser tab: observe, navigate, act.\n\nActions use real input events (`Input.dispatchMouseEvent`,\n`Input.insertText`) rather than `element.click()` or direct DOM mutation.\nSynthetic DOM calls skip the handlers that real sites depend on — and, unlike\nthe desktop keyboard path, CDP input goes to a specific renderer rather than a\nshared OS queue, so it does not suffer the dropped-character race that made\nkeystroke typing unreliable there.\n\nEvery action returns an `EffectState`, for the same reason it does everywhere\nelse: after a timeout an agent must not assume nothing happened.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport threading\nimport time\nfrom typing import Any\n\nfrom ..protocol import EffectState, ErrorCode, ProtocolError\nfrom . import perceive\nfrom .actionable import ensure_actionable\nfrom .cdp import CdpConnection\n\n\nclass Page:\n    def __init__(self, conn: CdpConnection, target_id: str, session_id: str) -> None:\n        self.conn = conn\n        self.target_id = target_id\n        self.session_id = session_id\n        self.refs = perceive.BrowserRefStore()\n        self._enabled = False\n        # Dialog policy: dismiss is Cancel for confirm(), OK for alert(), and\n        # \"stay on the page\" for beforeunload - the conservative choice in all\n        # three. An agent that needs to accept must say so explicitly.\n        self.dialog_policy = \"dismiss\"\n        self._dialogs: list[dict[str, Any]] = []\n        self._console: list[dict[str, Any]] = []\n        self._dialog_lock = threading.Lock()\n        # The URL the permission engine evaluates browser verbs against. Kept\n        # current by _page_info(), which every observation and action path\n        # already calls, so it cannot go stale by accident.\n        self.current_url: str = \"\"\n        # Observation continuation: the full text of the last token-budgeted\n        # observe, kept so `more` can hand out the rest without re-observing\n        # (which would invalidate every ref the agent is holding).\n        self._continuation: dict[str, Any] | None = None\n\n    # --- lifecycle ----------------------------------------------------------\n\n    def _on_event(self, method: str, params: dict[str, Any],\n                  sess: str | None) -> None:\n        \"\"\"Handle a blocking JavaScript dialog the moment it opens.\n\n        `alert()`, `confirm()`, `prompt()` and `beforeunload` **block the\n        renderer**. Until one is answered, every CDP command for that target\n        queues forever: measured here, a single `alert()` made `click` time out\n        at 20s and then wedged the session permanently - every later `observe`\n        timed out too. Nothing recovers it, because the reply can never arrive.\n\n        So the dialog is answered immediately and recorded, and the record is\n        attached to whatever action triggered it. The agent is told a dialog\n        appeared, what it said, and how it was answered, instead of receiving\n        an unexplained timeout.\n        \"\"\"\n        if sess != self.session_id:\n            return\n        if method in (\"Runtime.consoleAPICalled\", \"Log.entryAdded\"):\n            self._record_console(method, params)\n            return\n        if method != \"Page.javascriptDialogOpening\":\n            return\n        accept = self.dialog_policy == \"accept\"\n        record = {\"type\": params.get(\"type\"),\n                  \"message\": (params.get(\"message\") or \"\")[:300],\n                  \"url\": params.get(\"url\", \"\")[:200],\n                  \"answered\": \"accepted\" if accept else \"dismissed\"}\n        # Fire-and-forget: this runs on the reader thread, so waiting for the\n        # reply here would deadlock against the very thread that delivers it.\n        if not self.conn.post(\"Page.handleJavaScriptDialog\",\n                              {\"accept\": accept, \"promptText\": \"\"},\n                              session_id=self.session_id):\n            record[\"answered\"] = \"failed to send\"\n        with self._dialog_lock:\n            self._dialogs.append(record)\n\n    def _record_console(self, method: str, params: dict[str, Any]) -> None:\n        if method == \"Log.entryAdded\":\n            e = params.get(\"entry\") or {}\n            row = {\"level\": e.get(\"level\"), \"text\": (e.get(\"text\") or \"\")[:400],\n                   \"url\": (e.get(\"url\") or \"\")[:200], \"source\": e.get(\"source\")}\n        else:\n            args = params.get(\"args\") or []\n            text = \" \".join(\n                str(a.get(\"value\", a.get(\"description\", \"\")))[:200] for a in args)\n            row = {\"level\": params.get(\"type\"), \"text\": text[:400],\n                   \"source\": \"console\"}\n        with self._dialog_lock:\n            self._console.append(row)\n            if len(self._console) > 500:\n                del self._console[:-500]\n\n    def _take_dialogs(self) -> list[dict[str, Any]]:\n        with self._dialog_lock:\n            out, self._dialogs = self._dialogs, []\n        return out\n\n    def _with_dialogs(self, result: dict[str, Any]) -> dict[str, Any]:\n        seen = self._take_dialogs()\n        if seen:\n            result[\"dialogs\"] = seen\n            result[\"note\"] = (\n                f\"{len(seen)} JavaScript dialog(s) appeared and were \"\n                f\"{seen[0]['answered']}: {seen[0]['message'][:120]!r}. \"\n                \"The page may be in a different state than intended; observe \"\n                \"before continuing.\")\n        return result\n\n    def enable(self) -> None:\n        if self._enabled:\n            return\n        # Subscribe first: a dialog can open during the very first navigation.\n        self.conn.subscribe(self._on_event)\n        for domain in (\"Page\", \"DOM\", \"Runtime\", \"Accessibility\", \"Log\"):\n            try:\n                self.conn.send(f\"{domain}.enable\", session_id=self.session_id,\n                               timeout=15)\n            except ProtocolError:\n                # Accessibility.enable is unavailable on some targets; the tree\n                # can still be fetched. A missing optional domain must not\n                # abort the session.\n                pass\n        self._enabled = True\n\n    def navigate(self, url: str, *, timeout: float = 45.0) -> dict[str, Any]:\n        self.enable()\n        if \"://\" not in url:\n            url = \"https://\" + url\n        res = self.conn.send(\"Page.navigate\", {\"url\": url},\n                             session_id=self.session_id, timeout=timeout)\n        if res.get(\"errorText\"):\n            raise ProtocolError(\n                ErrorCode.INTERNAL,\n                f\"navigation failed: {res['errorText']}\",\n                hint=\"Check the URL and that the machine is online.\",\n                effect_state=EffectState.UNKNOWN)\n        self._await_ready(timeout=timeout)\n        self.refs.begin()  # a new document invalidates every ref\n        self._continuation = None   # ...and any pending observation chunks\n        # A new document wipes page-level hooks; reinstall so a popup opened by\n        # the next click is still captured rather than escaping control.\n        try:\n            self.install_popup_hook()\n        except ProtocolError:\n            pass\n        info = self._page_info()\n        out = self._with_dialogs({\"effect_state\": EffectState.COMMITTED.value,\n                                  \"url\": info[\"url\"], \"title\": info[\"title\"]})\n        # Google refuses sign-in from any debugger-controlled browser — a\n        # server-side decision on their side (Chromium issue 40746300), so no\n        # local setting changes it. Telling the agent the moment the wall is\n        # hit beats letting it retry the sign-in flow and fail repeatedly.\n        url = info[\"url\"].lower()\n        if \"accounts.google.com\" in url and \"rejected\" in url:\n            out[\"google_signin_blocked\"] = True\n            out[\"note\"] = (\n                \"Google rejected sign-in because this browser is under \"\n                \"automation control. This is a server-side block and cannot \"\n                \"be worked around from here - and should not be. For Gmail \"\n                \"and Google services, use the extension-based browser tool \"\n                \"that drives the user's own signed-in browser (e.g. bsk), or \"\n                \"have the user act in their own browser and deliver the work \"\n                \"as files.\")\n        return out\n\n    def _await_ready(self, timeout: float) -> None:\n        deadline = time.monotonic() + timeout\n        while time.monotonic() < deadline:\n            try:\n                r = self.conn.send(\n                    \"Runtime.evaluate\",\n                    {\"expression\": \"document.readyState\", \"returnByValue\": True},\n                    session_id=self.session_id, timeout=10)\n                if r.get(\"result\", {}).get(\"value\") in (\"interactive\", \"complete\"):\n                    return\n            except ProtocolError:\n                pass\n            time.sleep(0.15)\n\n    def _page_info(self) -> dict[str, Any]:\n        r = self.conn.send(\n            \"Runtime.evaluate\",\n            {\"expression\": \"JSON.stringify({u:location.href,t:document.title,\"\n                           \"w:innerWidth,h:innerHeight})\",\n             \"returnByValue\": True},\n            session_id=self.session_id, timeout=15)\n        import json\n        try:\n            d = json.loads(r[\"result\"][\"value\"])\n            self.current_url = d[\"u\"]\n            return {\"url\": d[\"u\"], \"title\": d[\"t\"],\n                    \"viewport\": (int(d[\"w\"]), int(d[\"h\"]))}\n        except Exception:\n            return {\"url\": \"\", \"title\": \"\", \"viewport\": (0, 0)}\n\n    # --- perception ---------------------------------------------------------\n\n    # Rough chars-per-token for the mixed prose+markup an observation holds.\n    CHARS_PER_TOKEN = 3.6\n\n    def observe(self, *, max_nodes: int = 2500,\n                max_tokens: int | None = None) -> dict[str, Any]:\n        self.enable()\n        started = time.monotonic()\n        info = self._page_info()\n        ax = self.conn.send(\"Accessibility.getFullAXTree\",\n                            session_id=self.session_id, timeout=60)\n        snap = self.conn.send(\"DOMSnapshot.captureSnapshot\",\n                              {\"computedStyles\": [], \"includeDOMRects\": True},\n                              session_id=self.session_id, timeout=60)\n        frame_trees = self._frame_trees()\n        obs = perceive.build(ax.get(\"nodes\", []), snap, self.refs,\n                             url=info[\"url\"], title=info[\"title\"],\n                             viewport=info[\"viewport\"], started=started,\n                             max_nodes=max_nodes, frame_trees=frame_trees)\n        text = perceive.render(obs)\n        out = {\"text\": text, **obs.to_dict(),\n               \"effect_state\": EffectState.NONE.value}\n        # A node cap is a proxy for what actually matters to the caller: how\n        # much of its context window the observation consumes. BrowserSkill\n        # budgets in tokens for exactly this reason, and used it on every\n        # single observe in the session recorded here.\n        if max_tokens:\n            limit = int(max_tokens * self.CHARS_PER_TOKEN)\n            self._continuation = {\"lines\": text.splitlines(), \"cursor\": 0,\n                                  \"generation\": self.refs.generation}\n            if len(text) > limit:\n                kept: list[str] = []\n                used = 0\n                lines = text.splitlines()\n                cut = len(lines)\n                for i, line in enumerate(lines):\n                    # `and kept`: a chunk must never be empty, even when the\n                    # very first line alone exceeds the whole budget.\n                    if used + len(line) + 1 > limit and kept:\n                        cut = i\n                        break\n                    kept.append(line)\n                    used += len(line) + 1\n                dropped = len(lines) - cut\n                # Hand out a cursor instead of only an apology: the rest of\n                # the observation is one `browser more` away, without\n                # re-observing and invalidating the refs just issued.\n                out[\"text\"] = \"\\n\".join(kept) + (\n                    f\"\\n\\n@more cursor={cut}  {dropped} lines follow; \"\n                    \"run `auto browser more \" + str(cut) +\n                    \"` to read them\")\n                out[\"truncated_lines\"] = dropped\n                out[\"cursor\"] = cut\n                self._continuation[\"cursor\"] = cut\n            out[\"est_tokens\"] = int(len(out[\"text\"]) / self.CHARS_PER_TOKEN)\n        return out\n\n    def more(self, cursor: int | None = None, *,\n             max_tokens: int = 3000) -> dict[str, Any]:\n        \"\"\"Continue a token-budgeted observation from where it was cut.\n\n        Re-observing would bump the ref generation and strand every ref the\n        agent is holding, so the full text of the last budgeted observe is\n        kept on the page and sliced here. The slice is checked against the\n        generation it was captured at: if the page changed, the rest is stale\n        and the honest answer is a refusal, not an old tree.\n        \"\"\"\n        cont = self._continuation\n        if not cont:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                \"nothing to continue: the last observe was not truncated \"\n                \"by --max-tokens\",\n                hint=\"Run `auto browser observe --max-tokens N` first.\")\n        if cont[\"generation\"] != self.refs.generation:\n            raise ProtocolError(\n                ErrorCode.STALE_REF,\n                \"the observation to continue is no longer current\",\n                hint=\"The page changed since that observe. Observe again.\")\n        at = int(cursor if cursor is not None else cont[\"cursor\"])\n        lines = cont[\"lines\"]\n        if not (0 <= at < len(lines)):\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                f\"cursor {at} is past the end ({len(lines)} lines)\",\n                hint=\"No more content; observe again only if the page changed.\")\n        limit = int(max_tokens * self.CHARS_PER_TOKEN)\n        kept: list[str] = []\n        used = 0\n        cut = len(lines)\n        for i in range(at, len(lines)):\n            line = lines[i]\n            if used + len(line) + 1 > limit and kept:\n                cut = i\n                break\n            kept.append(line)\n            used += len(line) + 1\n        out: dict[str, Any] = {\"effect_state\": EffectState.NONE.value,\n               \"text\": \"\\n\".join(kept), \"from_line\": at}\n        if cut < len(lines):\n            out[\"text\"] += (f\"\\n\\n@more cursor={cut}  \"\n                            f\"{len(lines) - cut} lines follow\")\n            out[\"cursor\"] = cut\n            cont[\"cursor\"] = cut\n        else:\n            out[\"text\"] += \"\\n\\n@end of observation\"\n            out[\"cursor\"] = None\n            cont[\"cursor\"] = len(lines)\n        out[\"est_tokens\"] = int(len(out[\"text\"]) / self.CHARS_PER_TOKEN)\n        return out\n\n    def _frame_trees(self) -> list[tuple[int, list[dict[str, Any]]]]:\n        \"\"\"One AX tree per child frame.\n\n        `getFullAXTree` covers a single frame, so an iframe's contents are\n        simply absent unless each frame is fetched explicitly. A frame that\n        cannot be read (cross-origin out-of-process, or torn down mid-call) is\n        skipped rather than failing the whole observation: a partial page is\n        far more useful than an error.\n        \"\"\"\n        out: list[tuple[int, list[dict[str, Any]]]] = []\n        try:\n            tree = self.conn.send(\"Page.getFrameTree\",\n                                  session_id=self.session_id, timeout=20)\n        except ProtocolError:\n            return out\n\n        def child_ids(node: dict[str, Any], depth: int = 0) -> list[str]:\n            if depth > 5:\n                return []\n            ids: list[str] = []\n            for child in node.get(\"childFrames\") or []:\n                fid = (child.get(\"frame\") or {}).get(\"id\")\n                if fid:\n                    ids.append(fid)\n                ids.extend(child_ids(child, depth + 1))\n            return ids\n\n        for fid in child_ids(tree.get(\"frameTree\") or {}):\n            try:\n                # The only reliable parent<->child link. A frame's own root\n                # node does not point back at the iframe element that hosts\n                # it, so without this the subtree cannot be placed.\n                owner = self.conn.send(\"DOM.getFrameOwner\", {\"frameId\": fid},\n                                       session_id=self.session_id, timeout=20)\n                host_id = owner.get(\"backendNodeId\")\n                if not isinstance(host_id, int):\n                    continue\n                res = self.conn.send(\"Accessibility.getFullAXTree\",\n                                     {\"frameId\": fid},\n                                     session_id=self.session_id, timeout=30)\n                nodes = res.get(\"nodes\") or []\n                if nodes:\n                    out.append((host_id, nodes))\n            except ProtocolError:\n                continue\n        return out\n\n    def _resolve(self, ref: str) -> dict[str, Any]:\n        entry = self.refs.get(ref if ref.startswith(\"@\") else \"@\" + ref)\n        if entry is None:\n            raise ProtocolError(\n                ErrorCode.UNKNOWN_REF,\n                f\"{ref} is not in the current observation \"\n                f\"({len(self.refs)} refs, generation {self.refs.generation})\",\n                hint=\"Run `auto browser observe` and use a ref from it.\")\n        if entry[\"generation\"] != self.refs.generation:\n            raise ProtocolError(\n                ErrorCode.STALE_REF, f\"{ref} is from an earlier observation\",\n                hint=\"The page changed. Observe again, then retry once.\")\n        return entry\n\n    def wait_for(self, text: str | None, *, timeout: float = 20.0) -> dict[str, Any]:\n        \"\"\"Wait until the page is ready, and optionally until `text` appears.\n\n        Polls the live DOM rather than sleeping a guessed interval, so a slow\n        page is tolerated and a fast one is not paid for.\n        \"\"\"\n        deadline = time.monotonic() + timeout\n        while time.monotonic() < deadline:\n            try:\n                expr = \"document.readyState\"\n                if text:\n                    esc = json.dumps(text)\n                    expr = (f\"(document.readyState!=='loading' && \"\n                            f\"document.body && \"\n                            f\"document.body.innerText.includes({esc})) \"\n                            f\"? 'ready' : 'waiting'\")\n                r = self.conn.send(\"Runtime.evaluate\",\n                                   {\"expression\": expr, \"returnByValue\": True},\n                                   session_id=self.session_id, timeout=15)\n                val = r.get(\"result\", {}).get(\"value\")\n                if (text and val == \"ready\") or                    (not text and val in (\"interactive\", \"complete\")):\n                    self.refs.begin()   # content changed; old refs are void\n                    return {\"effect_state\": EffectState.NONE.value,\n                            \"waited_s\": round(timeout - (deadline - time.monotonic()), 2),\n                            \"matched\": text or \"document ready\"}\n            except ProtocolError:\n                pass\n            time.sleep(0.25)\n        raise ProtocolError(\n            ErrorCode.TIMEOUT,\n            (f\"text {text!r} did not appear within {timeout:g}s\" if text\n             else f\"page was not ready within {timeout:g}s\"),\n            hint=\"Observe to see what the page actually contains.\")\n\n    # --- actions ------------------------------------------------------------\n\n    def _point_for(self, ref: str, entry: dict[str, Any], *,\n                   timeout: float = 5.0) -> tuple[float, float]:\n        \"\"\"Resolve a point that will actually reach the element.\n\n        Delegates to the actionability probe, which verifies visibility,\n        enablement, stability, viewport membership **and** that the element is\n        the real hit target - the last two being the checks whose absence\n        produced measured false successes.\n        \"\"\"\n        backend = entry.get(\"backend_id\")\n        if isinstance(backend, int):\n            label = f'{entry.get(\"role\",\"\")} {entry.get(\"name\",\"\")!r}'\n            # Pass the whole entry so a stale node can be re-located from its\n            # description (role, name, ordinal) instead of ending the task.\n            got = ensure_actionable(self.conn, self.session_id, backend, ref,\n                                    label, timeout=timeout, entry=entry)\n            return float(got[\"x\"]), float(got[\"y\"])\n        return self._point_for_legacy(ref, entry)\n\n    def _point_for_legacy(self, ref: str, entry: dict[str, Any]) -> tuple[float, float]:\n        \"\"\"Resolve a click point that is actually inside the viewport.\n\n        `Input.dispatchMouseEvent` takes **viewport** coordinates, while an\n        observation records **page** coordinates. For anything below the fold\n        those differ, and Chrome silently discards an event aimed outside the\n        viewport. The result was the worst failure this tool can produce: a\n        button 1400px down reported `effect_state: committed` at y=1647 in a\n        482px-tall viewport, and nothing happened.\n\n        So: scroll the element into view, re-read its box from the live DOM,\n        and refuse rather than report a success that did not occur.\n        \"\"\"\n        backend = entry.get(\"backend_id\")\n        if isinstance(backend, int):\n            try:\n                self.conn.send(\"DOM.scrollIntoViewIfNeeded\",\n                               {\"backendNodeId\": backend},\n                               session_id=self.session_id, timeout=20)\n                time.sleep(0.12)\n            except ProtocolError:\n                pass  # not scrollable (fixed/overlay); verified below anyway\n\n            box = None\n            try:\n                box = self.conn.send(\"DOM.getBoxModel\", {\"backendNodeId\": backend},\n                                     session_id=self.session_id, timeout=20)\n            except ProtocolError:\n                box = None\n            quad = ((box or {}).get(\"model\") or {}).get(\"border\")\n            if quad and len(quad) >= 8:\n                xs, ys = quad[0::2][:4], quad[1::2][:4]\n                cx, cy = sum(xs) / 4.0, sum(ys) / 4.0\n                # A zero-area box paints nothing of its own: the visible\n                # control is a child, a pseudo-element or pure padding. Its\n                # centroid is a point on a line, and dispatching there hits\n                # whatever else is at those coordinates while the caller is\n                # told the click landed. The fallback path below has always\n                # refused a zero-area rect; this path never checked, and it\n                # is the one actually used. Measured on a real approval\n                # button: [x=1460.3, y=12, w=49.7, h=0], comfortably inside\n                # the viewport and completely unclickable.\n                w = max(xs) - min(xs)\n                h = max(ys) - min(ys)\n                if w < 1 or h < 1:\n                    raise ProtocolError(\n                        ErrorCode.TARGET_NOT_VISIBLE,\n                        f\"{ref} has a zero-area box ({w:.0f}x{h:.0f}); a \"\n                        f\"click at its centre would not reach it\",\n                        hint=\"The element paints through a child or \"\n                             \"pseudo-element. Observe again and click the \"\n                             \"child that carries the box.\")\n                vw, vh = self._page_info()[\"viewport\"]\n                if 0 <= cx <= vw and 0 <= cy <= vh:\n                    return cx, cy\n                raise ProtocolError(\n                    ErrorCode.TARGET_NOT_VISIBLE,\n                    f\"{ref} is outside the viewport even after scrolling \"\n                    f\"(point {cx:.0f},{cy:.0f} vs viewport {vw}x{vh})\",\n                    hint=\"It may be inside a scrollable panel, hidden behind an \"\n                         \"overlay, or the page may have changed. Observe again.\")\n\n        # No backend id (or no box model): fall back to the recorded rect, but\n        # still refuse if it cannot be inside the viewport.\n        rect = entry.get(\"rect\")\n        if not rect or rect[2] <= 0 or rect[3] <= 0:\n            raise ProtocolError(\n                ErrorCode.TARGET_NOT_VISIBLE, f\"{ref} has no visible area\",\n                hint=\"Observe again; the element may have been removed.\")\n        cx, cy = rect[0] + rect[2] / 2, rect[1] + rect[3] / 2\n        vw, vh = self._page_info()[\"viewport\"]\n        if not (0 <= cx <= vw and 0 <= cy <= vh):\n            raise ProtocolError(\n                ErrorCode.TARGET_NOT_VISIBLE,\n                f\"{ref} sits at {cx:.0f},{cy:.0f}, outside the \"\n                f\"{vw}x{vh} viewport, and could not be scrolled into view\",\n                hint=\"Scroll the page, then observe and retry.\")\n        return cx, cy\n\n    def keep_awake(self) -> bool:\n        \"\"\"Ask the renderer to stay responsive without taking the screen.\n\n        This surface launches headful, so its window sits behind whatever the\n        user is doing, and an occluded renderer accepts input events without\n        running handlers — a click dispatches, nothing happens, no error is\n        raised. `rb` learned this and solved it with the same call; this\n        surface had nothing at all.\n        \"\"\"\n        try:\n            self.conn.send(\"Page.setWebLifecycleState\", {\"state\": \"active\"},\n                           session_id=self.session_id, timeout=10)\n            return True\n        except ProtocolError:\n            return False        # older target, or it refuses; not fatal\n\n    def click(self, ref: str, *, button: str = \"left\",\n              clicks: int = 1) -> dict[str, Any]:\n        entry = self._resolve(ref)\n        self.keep_awake()\n        x, y = self._point_for(ref, entry)\n        common = {\"x\": x, \"y\": y, \"button\": button, \"clickCount\": clicks}\n        try:\n            self.conn.send(\"Input.dispatchMouseEvent\",\n                           {\"type\": \"mousePressed\", **common},\n                           session_id=self.session_id, timeout=20)\n            self.conn.send(\"Input.dispatchMouseEvent\",\n                           {\"type\": \"mouseReleased\", **common},\n                           session_id=self.session_id, timeout=20)\n        except ProtocolError as exc:\n            exc.error.effect_state = EffectState.UNKNOWN\n            raise\n        return self._with_dialogs({\n            \"effect_state\": EffectState.COMMITTED.value,\n            \"target\": f'{ref} {entry[\"role\"]} {entry[\"name\"]!r}',\n            \"at\": [round(x), round(y)], \"actionable\": True})\n\n    def type_text(self, ref: str | None, text: str, *,\n                  clear: bool = False) -> dict[str, Any]:\n        if ref:\n            entry = self._resolve(ref)\n            if entry[\"sensitive\"]:\n                raise ProtocolError(\n                    ErrorCode.PERMISSION_DENIED,\n                    f\"{ref} is a password field\",\n                    hint=\"The agent never types credentials. Ask the user to \"\n                         \"enter it with `auto request-help`.\")\n            self.click(ref)\n            time.sleep(0.1)\n            if clear:\n                self.conn.send(\"Input.dispatchKeyEvent\",\n                               {\"type\": \"keyDown\", \"modifiers\": 2, \"key\": \"a\",\n                                \"code\": \"KeyA\", \"windowsVirtualKeyCode\": 65},\n                               session_id=self.session_id, timeout=15)\n                self.conn.send(\"Input.dispatchKeyEvent\",\n                               {\"type\": \"keyUp\", \"modifiers\": 2, \"key\": \"a\",\n                                \"code\": \"KeyA\", \"windowsVirtualKeyCode\": 65},\n                               session_id=self.session_id, timeout=15)\n        try:\n            # insertText delivers the whole string to the focused element in one\n            # renderer-side operation: no per-character race is possible.\n            self.conn.send(\"Input.insertText\", {\"text\": text},\n                           session_id=self.session_id, timeout=30)\n        except ProtocolError as exc:\n            exc.error.effect_state = EffectState.UNKNOWN\n            raise\n        return self._with_dialogs({\"effect_state\": EffectState.COMMITTED.value,\n                                   \"chars\": len(text), \"target\": ref})\n\n    def select_option(self, ref: str, *, value: str | None = None,\n                      label: str | None = None) -> dict[str, Any]:\n        \"\"\"Choose an option in a native <select>.\n\n        A native dropdown cannot be driven with synthetic mouse events: the\n        popup is rendered by the OS, not the page, so clicking the control only\n        opens something CDP cannot reach. The supported path is to set the\n        value on the element and fire the events a real selection would — which\n        is what the page's own handlers listen for.\n        \"\"\"\n        entry = self._resolve(ref)\n        backend = entry.get(\"backend_id\")\n        if not isinstance(backend, int):\n            raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                f\"{ref} cannot be resolved in the DOM\")\n        if value is None and label is None:\n            raise ProtocolError(ErrorCode.UNSUPPORTED,\n                                \"pass --value or --label\",\n                                hint=\"--value matches the option's value \"\n                                     \"attribute, --label its visible text.\")\n        obj = self.conn.send(\"DOM.resolveNode\", {\"backendNodeId\": backend},\n                             session_id=self.session_id, timeout=20)\n        object_id = (obj.get(\"object\") or {}).get(\"objectId\")\n        if not object_id:\n            raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                f\"{ref} is no longer attached to the document\")\n\n        fn = \"\"\"\n        function(wantValue, wantLabel) {\n          if (this.tagName !== 'SELECT') return {ok:false, reason:'not_a_select',\n                                                 tag:this.tagName};\n          const opts = Array.from(this.options);\n          let idx = -1;\n          if (wantValue !== null) idx = opts.findIndex(o => o.value === wantValue);\n          if (idx < 0 && wantLabel !== null)\n            idx = opts.findIndex(o => o.text.trim() === String(wantLabel).trim());\n          if (idx < 0) return {ok:false, reason:'no_match',\n                               options: opts.map(o => ({value:o.value, label:o.text.trim()}))};\n          this.selectedIndex = idx;\n          this.dispatchEvent(new Event('input', {bubbles:true}));\n          this.dispatchEvent(new Event('change', {bubbles:true}));\n          return {ok:true, value:this.value, label:opts[idx].text.trim()};\n        }\n        \"\"\"\n        res = self.conn.send(\n            \"Runtime.callFunctionOn\",\n            {\"objectId\": object_id, \"functionDeclaration\": fn,\n             \"arguments\": [{\"value\": value}, {\"value\": label}],\n             \"returnByValue\": True},\n            session_id=self.session_id, timeout=20)\n        out = (res.get(\"result\") or {}).get(\"value\") or {}\n        if not out.get(\"ok\"):\n            if out.get(\"reason\") == \"not_a_select\":\n                raise ProtocolError(\n                    ErrorCode.UNSUPPORTED,\n                    f\"{ref} is a <{out.get('tag','?')}>, not a native <select>\",\n                    hint=\"For a custom dropdown, click it and then click the \"\n                         \"option that appears in the next observation.\")\n            offered = out.get(\"options\") or []\n            listing = \", \".join(f\"{o['label']!r} (value={o['value']!r})\"\n                                for o in offered[:8])\n            raise ProtocolError(\n                ErrorCode.TARGET_NOT_FOUND,\n                f\"no option in {ref} matched \"\n                f\"{'value ' + repr(value) if value else 'label ' + repr(label)}\",\n                hint=f\"Available: {listing}\" if listing else \"The select is empty.\")\n        return {\"effect_state\": EffectState.COMMITTED.value, \"target\": ref,\n                \"selected_value\": out.get(\"value\"),\n                \"selected_label\": out.get(\"label\")}\n\n    POPUP_HOOK = \"\"\"\n    (() => {\n      if (window.__autoskillPopupHook) return 'present';\n      window.__autoskillPopups = [];\n      window.open = function (u, n, f) {\n        try { window.__autoskillPopups.push({url: String(u || ''),\n                                             name: String(n || ''),\n                                             at: Date.now()}); } catch (e) {}\n        return {closed: false, focus() {}, blur() {},\n                close() { this.closed = true; }, postMessage() {},\n                location: {href: String(u || '')}, document: null};\n      };\n      window.__autoskillPopupHook = true;\n      return 'installed';\n    })()\n    \"\"\"\n\n    def install_popup_hook(self) -> dict[str, Any]:\n        \"\"\"Capture `window.open` instead of letting a popup escape control.\n\n        A page-opened window is not a controlled tab: it appears outside the\n        automation's ownership, so the agent can neither read nor act on it.\n        Replacing `window.open` turns an uncontrollable popup into a URL the\n        agent can navigate to deliberately, in a tab it owns. The stand-in\n        object keeps page code that calls `.focus()` or `.close()` on the\n        result from throwing and abandoning the flow half-done.\n\n        The hook lives in the document, so a navigation wipes it; it is\n        reinstalled after every navigate.\n        \"\"\"\n        r = self.conn.send(\"Runtime.evaluate\",\n                           {\"expression\": self.POPUP_HOOK, \"returnByValue\": True},\n                           session_id=self.session_id, timeout=20)\n        return {\"effect_state\": EffectState.NONE.value,\n                \"hook\": (r.get(\"result\") or {}).get(\"value\")}\n\n    def popups(self, *, clear: bool = False) -> dict[str, Any]:\n        tail = (\"const c = p.slice(); window.__autoskillPopups = []; \"\n                \"return JSON.stringify({hook: !!window.__autoskillPopupHook, popups: c});\"\n                if clear else\n                \"return JSON.stringify({hook: !!window.__autoskillPopupHook, popups: p});\")\n        expr = \"(() => { const p = window.__autoskillPopups || []; \" + tail + \" })()\"\n        r = self.conn.send(\"Runtime.evaluate\",\n                           {\"expression\": expr, \"returnByValue\": True},\n                           session_id=self.session_id, timeout=20)\n        try:\n            data = json.loads((r.get(\"result\") or {}).get(\"value\") or \"{}\")\n        except Exception:\n            data = {}\n        out = {\"effect_state\": EffectState.NONE.value,\n               \"popups\": data.get(\"popups\") or [],\n               \"hook_active\": bool(data.get(\"hook\"))}\n        if not out[\"hook_active\"]:\n            out[\"note\"] = (\"the hook is not installed on this document - it is \"\n                           \"wiped by navigation, so popups opened before \"\n                           \"installation were not captured\")\n        return out\n\n    EXTRACTORS = {\n        \"text\": \"document.body ? document.body.innerText.replace(/\\\\s+/g,' ').trim() : ''\",\n        \"links\": (\"JSON.stringify([...document.querySelectorAll('a[href]')]\"\n                  \".slice(0,400).map(a => ({text: a.textContent.trim().slice(0,120),\"\n                  \" href: a.href})))\"),\n        \"tables\": (\"JSON.stringify([...document.querySelectorAll('table')].slice(0,20)\"\n                   \".map(t => [...t.rows].slice(0,200).map(r =>\"\n                   \" [...r.cells].slice(0,30).map(c => c.innerText.trim().slice(0,120)))))\"),\n        \"title\": \"JSON.stringify({title: document.title, url: location.href})\",\n        \"meta\": (\"JSON.stringify([...document.querySelectorAll('meta[name],meta[property]')]\"\n                 \".slice(0,60).map(m => ({k: m.name || m.getAttribute('property'),\"\n                 \" v: (m.content || '').slice(0,200)})))\"),\n    }\n\n    def extract(self, kind: str, *, ref: str | None = None,\n                max_chars: int = 20000) -> dict[str, Any]:\n        \"\"\"Structured extraction with fixed, audited scripts.\n\n        27% of the calls in the recorded BrowserSkill session were `evaluate`,\n        and most were extraction: bounded `innerText`, link lists, a regex over\n        the URL. The capability is genuinely needed, because a semantic tree is\n        the wrong shape for \"give me this table\".\n\n        Exposing arbitrary JavaScript to get it would hand an agent a way around\n        every guard in this tool, so the scripts are fixed and reviewed here.\n        Each is bounded in both element count and string length.\n        \"\"\"\n        if kind not in self.EXTRACTORS:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED, \"unknown extractor \" + repr(kind),\n                hint=\"Available: \" + \", \".join(sorted(self.EXTRACTORS)))\n\n        if ref and kind == \"text\":\n            entry = self._resolve(ref)\n            backend = entry.get(\"backend_id\")\n            if isinstance(backend, int):\n                obj = self.conn.send(\"DOM.resolveNode\", {\"backendNodeId\": backend},\n                                     session_id=self.session_id, timeout=20)\n                oid = (obj.get(\"object\") or {}).get(\"objectId\")\n                if oid:\n                    fn = (\"function(){ return this.innerText ? \"\n                          \"this.innerText.replace(/\\\\s+/g,' ').trim() : ''; }\")\n                    r = self.conn.send(\n                        \"Runtime.callFunctionOn\",\n                        {\"objectId\": oid, \"functionDeclaration\": fn,\n                         \"returnByValue\": True},\n                        session_id=self.session_id, timeout=30)\n                    val = str((r.get(\"result\") or {}).get(\"value\") or \"\")\n                    return {\"effect_state\": EffectState.NONE.value, \"kind\": kind,\n                            \"data\": val[:max_chars], \"chars\": len(val),\n                            \"truncated\": len(val) > max_chars}\n\n        r = self.conn.send(\"Runtime.evaluate\",\n                           {\"expression\": self.EXTRACTORS[kind],\n                            \"returnByValue\": True},\n                           session_id=self.session_id, timeout=60)\n        extracted = (r.get(\"result\") or {}).get(\"value\")\n        text = extracted if isinstance(extracted, str) else json.dumps(extracted, ensure_ascii=False)\n        data = text[:max_chars]\n        if kind in (\"links\", \"tables\", \"meta\", \"title\"):\n            try:\n                data = json.loads(text)\n            except Exception:\n                pass\n        return {\"effect_state\": EffectState.NONE.value, \"kind\": kind,\n                \"data\": data, \"chars\": len(text),\n                \"truncated\": len(text) > max_chars}\n\n    def hover(self, ref: str) -> dict[str, Any]:\n        \"\"\"Move the pointer over an element so hover-only content appears.\n\n        Menus that render on hover simply do not exist in the tree until the\n        pointer is over their trigger. Look for `[has-submenu]` in an\n        observation, hover that ref, then observe again and use the revealed\n        item - its ref does not exist before the hover.\n        \"\"\"\n        entry = self._resolve(ref)\n        x, y = self._point_for(ref, entry)\n        self.conn.send(\"Input.dispatchMouseEvent\",\n                       {\"type\": \"mouseMoved\", \"x\": x, \"y\": y},\n                       session_id=self.session_id, timeout=20)\n        time.sleep(0.35)\n        return self._with_dialogs({\n            \"effect_state\": EffectState.NONE.value,\n            \"target\": f'{ref} {entry[\"role\"]} {entry[\"name\"]!r}',\n            \"at\": [round(x), round(y)],\n            \"note\": \"observe again; hover-revealed items have new refs\"})\n\n    def get_html(self, *, ref: str | None = None,\n                 max_chars: int = 200_000) -> dict[str, Any]:\n        \"\"\"Exact markup, for hidden metadata the accessibility tree drops.\"\"\"\n        if ref:\n            entry = self._resolve(ref)\n            backend = entry.get(\"backend_id\")\n            if not isinstance(backend, int):\n                raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                    f\"{ref} is not resolvable in the DOM\")\n            res = self.conn.send(\"DOM.getOuterHTML\", {\"backendNodeId\": backend},\n                                 session_id=self.session_id, timeout=60)\n            html = res.get(\"outerHTML\", \"\")\n        else:\n            r = self.conn.send(\n                \"Runtime.evaluate\",\n                {\"expression\": \"document.documentElement.outerHTML\",\n                 \"returnByValue\": True},\n                session_id=self.session_id, timeout=60)\n            html = str((r.get(\"result\") or {}).get(\"value\") or \"\")\n        truncated = len(html) > max_chars\n        return {\"effect_state\": EffectState.NONE.value,\n                \"html\": html[:max_chars], \"chars\": len(html),\n                \"truncated\": truncated,\n                **({\"note\": f\"truncated to {max_chars} chars\"} if truncated else {})}\n\n    def console(self, limit: int = 50) -> dict[str, Any]:\n        with self._dialog_lock:\n            entries = list(self._console)[-limit:]\n        return {\"effect_state\": EffectState.NONE.value,\n                \"entries\": entries, \"count\": len(entries)}\n\n    def press(self, key: str) -> dict[str, Any]:\n        spec = _KEYS.get(key.lower())\n        if spec is None:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED, f\"unsupported key {key!r}\",\n                hint=f\"Known: {', '.join(sorted(_KEYS))}\")\n        for kind in (\"keyDown\", \"keyUp\"):\n            self.conn.send(\"Input.dispatchKeyEvent\",\n                           {\"type\": kind, **spec},\n                           session_id=self.session_id, timeout=15)\n        return self._with_dialogs(\n            {\"effect_state\": EffectState.COMMITTED.value, \"key\": key})\n\n    def history(self, delta: int = -1) -> dict[str, Any]:\n        entries = self.conn.send(\"Page.getNavigationHistory\",\n                                 session_id=self.session_id, timeout=20)\n        idx = entries.get(\"currentIndex\", 0)\n        items = entries.get(\"entries\") or []\n        target = idx + delta\n        if not (0 <= target < len(items)):\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                f\"cannot move {delta:+d} in history \"\n                f\"(at {idx} of {len(items)})\",\n                hint=\"There is nothing to go back or forward to.\")\n        self.conn.send(\"Page.navigateToHistoryEntry\",\n                       {\"entryId\": items[target][\"id\"]},\n                       session_id=self.session_id, timeout=30)\n        self._await_ready(timeout=30)\n        self.refs.begin()\n        info = self._page_info()\n        return {\"effect_state\": EffectState.COMMITTED.value,\n                \"url\": info[\"url\"], \"title\": info[\"title\"]}\n\n    def reload(self) -> dict[str, Any]:\n        self.conn.send(\"Page.reload\", {}, session_id=self.session_id, timeout=30)\n        self._await_ready(timeout=30)\n        self.refs.begin()\n        info = self._page_info()\n        return {\"effect_state\": EffectState.COMMITTED.value,\n                \"url\": info[\"url\"], \"title\": info[\"title\"]}\n\n    def _scroll_pos(self) -> tuple[int, int]:\n        try:\n            r = self.conn.send(\n                \"Runtime.evaluate\",\n                {\"expression\": \"[Math.round(scrollX),Math.round(scrollY)].join(',')\",\n                 \"returnByValue\": True},\n                session_id=self.session_id, timeout=15)\n            x, y = str(r[\"result\"][\"value\"]).split(\",\")\n            return int(x), int(y)\n        except Exception:\n            return -1, -1\n\n    def scroll(self, *, delta_y: int | None = None,\n               delta_x: int | None = None) -> dict[str, Any]:\n        \"\"\"Scroll the page, then report how far it actually moved.\n\n        Two things were wrong before. `delta_y` defaulted to 400, so asking for\n        a purely horizontal scroll also moved the page down by 400px without\n        being asked. And the result claimed `committed` without checking\n        anything had moved, so a page already at its limit looked identical to\n        one that scrolled.\n        \"\"\"\n        if delta_x is None and delta_y is None:\n            delta_y = 400          # a bare `scroll` still means \"down a page\"\n        dx, dy = int(delta_x or 0), int(delta_y or 0)\n        if dx == 0 and dy == 0:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED, \"scroll needs a non-zero delta\",\n                hint=\"Pass --delta-y (down is positive) or --delta-x \"\n                     \"(right is positive).\")\n\n        before = self._scroll_pos()\n        info = self._page_info()\n        vw, vh = info[\"viewport\"]\n        self.conn.send(\"Input.dispatchMouseEvent\",\n                       {\"type\": \"mouseWheel\", \"x\": vw // 2, \"y\": vh // 2,\n                        \"deltaX\": dx, \"deltaY\": dy},\n                       session_id=self.session_id, timeout=15)\n        time.sleep(0.18)\n        after = self._scroll_pos()\n\n        moved_x, moved_y = after[0] - before[0], after[1] - before[1]\n        out = {\"effect_state\": EffectState.COMMITTED.value,\n               \"requested\": {\"x\": dx, \"y\": dy},\n               \"from\": {\"x\": before[0], \"y\": before[1]},\n               \"to\": {\"x\": after[0], \"y\": after[1]},\n               \"moved\": {\"x\": moved_x, \"y\": moved_y}}\n        if before != (-1, -1) and moved_x == 0 and moved_y == 0:\n            out[\"effect_state\"] = EffectState.NONE.value\n            out[\"note\"] = (\"nothing moved - the page is already at its limit \"\n                           \"in that direction, or the scrollable area is a \"\n                           \"panel rather than the page\")\n        return out\n\n    def screenshot(self, out_path: str, *, full_page: bool = False,\n                   lazy: bool = False, timeout: float = 120.0) -> dict[str, Any]:\n        \"\"\"Capture the viewport, or the whole page.\n\n        `captureBeyondViewport` renders the full document in one pass, which is\n        enough for ordinary pages. It is *not* enough for lazily loaded content:\n        images and feed items below the fold never render because they were\n        never scrolled into view, so the tall image is full of blanks.\n\n        `lazy=True` scrolls the page first to trigger that loading, stops when\n        the document stops growing, and restores the original scroll position.\n        It reports the height it settled at rather than claiming everything\n        loaded — an infinite feed never finishes, and saying otherwise would be\n        a lie the agent passes on to the user.\n        \"\"\"\n        import base64\n        from pathlib import Path\n\n        grew_to = None\n        if full_page and lazy:\n            grew_to = self._settle_lazy_content(timeout=min(timeout, 60))\n\n        params: dict[str, Any] = {\"format\": \"png\"}\n        if full_page:\n            params[\"captureBeyondViewport\"] = True\n        res = self.conn.send(\"Page.captureScreenshot\", params,\n                             session_id=self.session_id, timeout=timeout)\n        data = base64.b64decode(res[\"data\"])\n        p = Path(out_path)\n        p.parent.mkdir(parents=True, exist_ok=True)\n        p.write_bytes(data)\n        out = {\"effect_state\": EffectState.NONE.value, \"path\": str(p),\n               \"bytes\": len(data), \"full_page\": full_page}\n        if grew_to is not None:\n            out[\"captured_height\"] = grew_to[\"height\"]\n            out[\"settled\"] = grew_to[\"settled\"]\n            if not grew_to[\"settled\"]:\n                out[\"note\"] = (\"the page kept growing; this capture covers \"\n                               f\"{grew_to['height']}px, not necessarily all content\")\n        return out\n\n    def _settle_lazy_content(self, *, timeout: float) -> dict[str, Any]:\n        \"\"\"Scroll to the bottom until the document stops growing.\"\"\"\n        start = self.conn.send(\n            \"Runtime.evaluate\",\n            {\"expression\": \"window.scrollY\", \"returnByValue\": True},\n            session_id=self.session_id, timeout=15).get(\"result\", {}).get(\"value\", 0)\n\n        deadline = time.monotonic() + timeout\n        last_h, stable = -1, 0\n        height = 0\n        while time.monotonic() < deadline:\n            r = self.conn.send(\n                \"Runtime.evaluate\",\n                {\"expression\": \"window.scrollTo(0, document.body.scrollHeight);\"\n                               \"document.body.scrollHeight\",\n                 \"returnByValue\": True},\n                session_id=self.session_id, timeout=15)\n            height = int(r.get(\"result\", {}).get(\"value\") or 0)\n            if height == last_h:\n                stable += 1\n                if stable >= 3:\n                    break\n            else:\n                stable = 0\n                last_h = height\n            time.sleep(0.4)\n\n        self.conn.send(\"Runtime.evaluate\",\n                       {\"expression\": f\"window.scrollTo(0, {start})\"},\n                       session_id=self.session_id, timeout=15)\n        time.sleep(0.2)\n        return {\"height\": height, \"settled\": stable >= 3}\n\n\n_KEYS: dict[str, dict[str, Any]] = {\n    \"enter\": {\"key\": \"Enter\", \"code\": \"Enter\", \"windowsVirtualKeyCode\": 13,\n              \"text\": \"\\r\"},\n    \"tab\": {\"key\": \"Tab\", \"code\": \"Tab\", \"windowsVirtualKeyCode\": 9},\n    \"escape\": {\"key\": \"Escape\", \"code\": \"Escape\", \"windowsVirtualKeyCode\": 27},\n    \"esc\": {\"key\": \"Escape\", \"code\": \"Escape\", \"windowsVirtualKeyCode\": 27},\n    \"backspace\": {\"key\": \"Backspace\", \"code\": \"Backspace\",\n                  \"windowsVirtualKeyCode\": 8},\n    \"delete\": {\"key\": \"Delete\", \"code\": \"Delete\", \"windowsVirtualKeyCode\": 46},\n    \"arrowdown\": {\"key\": \"ArrowDown\", \"code\": \"ArrowDown\",\n                  \"windowsVirtualKeyCode\": 40},\n    \"arrowup\": {\"key\": \"ArrowUp\", \"code\": \"ArrowUp\", \"windowsVirtualKeyCode\": 38},\n    \"arrowleft\": {\"key\": \"ArrowLeft\", \"code\": \"ArrowLeft\",\n                  \"windowsVirtualKeyCode\": 37},\n    \"arrowright\": {\"key\": \"ArrowRight\", \"code\": \"ArrowRight\",\n                   \"windowsVirtualKeyCode\": 39},\n}\n");
